<div class="section-heading"><div><div class="eyebrow">Catálogo</div><h1>Produtos<?=$stockEnabled?' e estoque':''?></h1><p class="text-secondary mb-0"><?=$stockEnabled?'Controle produtos e saldos disponíveis.':'Seu plano inclui produtos e vendas; o controle de estoque não está contratado.'?></p></div></div>
<?php if(\App\Core\Authorization::allows('products.create')):?><div class="card mb-4"><div class="card-body"><form method="post" action="/products" class="row g-2"><?php echo \App\Core\CSRF::field();?><div class="col-md-3"><input class="form-control" name="name" placeholder="Produto" required></div><div class="col-md-2"><input class="form-control" name="sku" placeholder="SKU"></div><div class="col-md-2"><input class="form-control" name="category" placeholder="Categoria"></div><div class="col"><input class="form-control" type="number" step=".01" min="0" name="cost_price" placeholder="Custo"></div><div class="col"><input class="form-control" type="number" step=".01" min="0" name="sale_price" placeholder="Venda" required></div><?php if($stockEnabled):?><div class="col"><input class="form-control" type="number" step=".001" min="0" name="stock" placeholder="Estoque"></div><?php endif;?><input type="hidden" name="commission_type" value="none"><input type="hidden" name="commission_value" value="0"><div class="col"><button class="btn btn-primary">Salvar</button></div></form></div></div><?php endif;?>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Produto</th><th>SKU</th><th>Venda</th><?php if($stockEnabled):?><th>Estoque</th><?php endif;?><th>Status</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><strong><?=htmlspecialchars($p['name'])?></strong><div class="small text-secondary"><?=htmlspecialchars($p['category']??'')?></div></td><td><?=htmlspecialchars($p['sku']??'')?></td><td>R$ <?=number_format((float)$p['sale_price'],2,',','.')?></td><?php if($stockEnabled):?><td><?=number_format((float)$p['stock'],3,',','.')?><?php if((float)$p['stock']<=(float)$p['minimum_stock']):?> <span class="badge text-bg-warning">baixo</span><?php endif;?></td><?php endif;?><td><span class="badge text-bg-<?=$p['active']?'success':'secondary'?>"><?=$p['active']?'Ativo':'Inativo'?></span></td><td class="text-end"><?php if(\App\Core\Authorization::allows('products.edit')):?><a class="btn btn-sm btn-outline-primary" href="/products/<?=(int)$p['id']?>/edit">Editar</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$products):?><tr><td colspan="6" class="text-center py-5 text-secondary">Nenhum produto cadastrado.</td></tr><?php endif;?></tbody></table></div></div>
